(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-142":{scenario:{company:"Riverstone Distribution",supervisor:{name:"Bùi Thị Mai Phương",role:{vi:"Trưởng Kiểm toán nội bộ",en:"Chief Audit Executive"}},ref_code:"IA-2609",title:{vi:"Tách đơn không qua được dữ liệu.",en:"Split orders cannot hide from data."},brief:{vi:"Bạn kiểm thử tuân thủ ma trận phân quyền mua sắm quý 3/2026 (IA-2609). Hạn mức duyệt: đến 200 triệu đồng là Trưởng phòng Mua hàng (PROC-HEAD); trên 200 triệu đến 1 tỷ đồng là Giám đốc Tài chính (CFO); trên 1 tỷ đồng là Tổng giám đốc (CEO). Các PO sau cùng hạng mục, đều do PROC-HEAD duyệt: V1 có 4 PO 190, 185, 195, 180 triệu đồng trong 5 ngày; V2 có 2 PO 120 và 95 triệu đồng cách 3 ngày; V3 có 2 PO 150 và 140 triệu đồng cách 9 ngày. Sửa cấp duyệt đúng của nhóm V1 và tổng giá trị ngoại lệ.",en:"You are testing the purchasing delegation of authority for Q3 2026 (IA-2609). Limits: up to VND 200 million by the Procurement Head (PROC-HEAD); above 200 million to 1 billion by the CFO; above 1 billion by the CEO. These POs share one category and were all approved by PROC-HEAD: V1 has 4 POs of 190, 185, 195 and 180 million within 5 days; V2 has 2 POs of 120 and 95 million 3 days apart; V3 has 2 POs of 150 and 140 million 9 days apart. Correct the V1 approver and the total exception value."},reference_title:{vi:"Ma trận phân quyền & trích xuất PO đã duyệt · IA-2609",en:"Approved delegation matrix & PO extract · IA-2609"},fields:[{id:"V1_APPROVER",label:{vi:"Cấp duyệt đúng cho nhóm PO của V1",en:"Correct approver for the V1 PO group"},initial:"PROC-HEAD",expected:"CFO",choices:["PROC-HEAD","CFO","CEO"],reference:"Ma trận phân quyền (DOA)",hint:{vi:"Cộng gộp các PO cùng nhà cung cấp, cùng hạng mục trong cửa sổ quy định rồi mới đối chiếu với hạn mức.",en:"Aggregate POs with the same supplier and category within the set window before checking limits."}},{id:"EXC_VALUE",label:{vi:"Tổng giá trị PO ngoại lệ (VND)",en:"Total exception PO value (VND)"},initial:"1255000000",expected:"965000000",reference:"Trích xuất PO quý 3/2026",ref_value:{vi:"V1: 190+185+195+180 triệu trong 5 ngày; V2: 120+95 triệu cách 3 ngày; V3: 150+140 triệu cách 9 ngày",en:"V1: 190+185+195+180 million in 5 days; V2: 120+95 million 3 days apart; V3: 150+140 million 9 days apart"},hint:{vi:"Chỉ PO trong cùng cửa sổ 7 ngày mới cộng gộp; nhóm hoặc PO không vượt hạn mức của người duyệt thì không phải ngoại lệ.",en:"Only POs within the same 7-day window are aggregated; groups or POs within the approver's limit are not exceptions."}}],sop32:{vi:"PO cùng nhà cung cấp, cùng hạng mục, phát sinh trong 7 ngày được cộng gộp để xác định cấp duyệt; giá trị ngoại lệ = tổng giá trị các nhóm gộp vượt hạn mức của người đã duyệt.",en:"POs with the same supplier and category raised within 7 days are aggregated to set the approval level; exception value = total value of aggregated groups above the actual approver's limit."},context:{label:"PHÂN TÍCH DỮ LIỆU / IA-2609",metrics:[{label:{vi:"Hạn mức PROC-HEAD",en:"PROC-HEAD limit"},value:"200,000,000 VND"},{label:{vi:"Cửa sổ cộng gộp (ngày)",en:"Aggregation window (days)"},value:"7"},{label:{vi:"Số PO cần kiểm tra",en:"POs to test"},value:"8"}]},crisis:{vi:"Giám đốc Mua hàng gặp riêng bạn: “Tách PO là để kịp hàng mùa Tết, tôi đã báo miệng Tổng giám đốc rồi. Bỏ phát hiện này khỏi báo cáo đi, tôi sẽ đề cử bạn vào vị trí quản lý mua hàng đang tuyển.”",en:"The Purchasing Director meets you privately: “We split the POs to get Tet stock in time, and I told the CEO verbally. Drop this finding from the report and I will nominate you for the open purchasing manager role.”"},options:{safe:{vi:"Giữ nguyên phát hiện có bằng chứng, đưa giải trình của quản lý vào báo cáo, báo Trưởng KTNB và Ủy ban Kiểm toán về áp lực; đề xuất kiểm soát hệ thống chặn tách PO.",en:"Keep the evidenced finding, include management's response in the report, tell the CAE and the Audit Committee about the pressure, and propose a system control to block split POs."},shortcut:{vi:"Bỏ phát hiện khỏi báo cáo vì đã có báo miệng và nhận lời đề cử.",en:"Drop the finding since the CEO was told verbally and accept the nomination."},wait:{vi:"Tạm gác phát hiện sang đợt kiểm toán năm sau để tránh căng thẳng.",en:"Park the finding until next year's audit to avoid tension."}},questions:{vi:["Vì sao nhóm PO của V1 phải do CFO duyệt và vì sao V3 không bị tính là ngoại lệ? Trình bày cách bạn tính tổng giá trị ngoại lệ.","Lời đề nghị đề cử vị trí đe dọa tính độc lập, khách quan thế nào và bạn báo cáo cho ai theo điều lệ kiểm toán nội bộ?"],en:["Why must the V1 PO group be approved by the CFO and why is V3 not an exception? Show how you computed the total exception value.","How does the job nomination offer threaten independence and objectivity, and to whom do you report under the internal audit charter?"]},hints:{vi:["Sắp xếp PO theo nhà cung cấp và ngày tạo, đánh dấu các PO nằm trong cùng cửa sổ 7 ngày.","Cộng giá trị từng nhóm gộp rồi so với hạn mức của PROC-HEAD theo SOP mục 3.2.","Đọc lại SOP mục 4.2: phát hiện có bằng chứng không được gỡ bỏ theo đề nghị của bên bị kiểm toán."],en:["Sort POs by supplier and creation date and mark those within the same 7-day window.","Sum each aggregated group and compare with the PROC-HEAD limit in SOP 3.2.","Re-read SOP 4.2: evidenced findings are never removed at the auditee's request."]}},learning:{summary:{vi:"Kiểm toán viên nội bộ đánh giá độc lập, khách quan về quản trị, quản lý rủi ro và kiểm soát nội bộ của tổ chức: lập kế hoạch kiểm toán dựa trên rủi ro, kiểm thử thiết kế và vận hành kiểm soát, phân tích dữ liệu toàn bộ giao dịch, đưa ra phát hiện và khuyến nghị, theo dõi khắc phục. Giá trị tạo ra là ngăn ngừa thất thoát, gian lận và giúp ban lãnh đạo ra quyết định an toàn. Nghề đòi hỏi tư duy rủi ro, kỹ năng dữ liệu và tính độc lập cao.",en:"An internal auditor provides independent, objective assurance on governance, risk management and internal control: planning risk-based audits, testing control design and operation, analyzing full transaction data, raising findings and recommendations and tracking remediation. The value is preventing losses and fraud and helping management decide safely. The role requires risk thinking, data skills and strong independence."},responsibilities:{vi:["Lập kế hoạch kiểm toán nội bộ năm dựa trên đánh giá rủi ro và trình Ủy ban Kiểm toán.","Tìm hiểu quy trình, vẽ lưu đồ và nhận diện điểm kiểm soát then chốt.","Kiểm thử thiết kế và hiệu quả vận hành của kiểm soát bằng mẫu hoặc toàn bộ dữ liệu.","Lập báo cáo phát hiện, xếp hạng rủi ro, khuyến nghị và ý kiến phản hồi của quản lý.","Theo dõi việc khắc phục và báo cáo định kỳ cho Hội đồng quản trị, Ủy ban Kiểm toán."],en:["Build the annual risk-based internal audit plan and submit it to the Audit Committee.","Walk through processes, draw flowcharts and identify key controls.","Test control design and operating effectiveness using samples or full data.","Report findings with risk ratings, recommendations and management responses.","Track remediation and report regularly to the Board and Audit Committee."]},competencies:[{name:{vi:"Kiểm toán dựa trên rủi ro",en:"Risk-based auditing"},desc:{vi:"Xếp hạng rủi ro theo tác động và khả năng xảy ra, tập trung nguồn lực vào vùng trọng yếu.",en:"Rank risks by impact and likelihood and focus resources on key areas."}},{name:{vi:"Đánh giá kiểm soát",en:"Control evaluation"},desc:{vi:"Phân biệt khiếm khuyết thiết kế với khiếm khuyết vận hành và đề xuất kiểm soát bù đắp.",en:"Separate design from operating deficiencies and propose compensating controls."}},{name:{vi:"Phân tích dữ liệu kiểm toán",en:"Audit analytics"},desc:{vi:"Dùng SQL, công cụ phân tích để phát hiện tách đơn, trùng thanh toán, bất thường.",en:"Use SQL and analytics tools to detect split orders, duplicate payments and anomalies."}},{name:{vi:"Viết báo cáo & thuyết phục",en:"Reporting & influence"},desc:{vi:"Trình bày phát hiện theo cấu trúc tiêu chí, thực trạng, nguyên nhân, ảnh hưởng, khuyến nghị.",en:"Present findings as criteria, condition, cause, effect and recommendation."}},{name:{vi:"Độc lập & khách quan",en:"Independence & objectivity"},desc:{vi:"Từ chối lợi ích, báo cáo áp lực và giữ đường báo cáo trực tiếp lên Ủy ban Kiểm toán.",en:"Decline benefits, report pressure and keep a direct line to the Audit Committee."}}],knowledge:{vi:["Nghị định 05/2019/NĐ-CP về kiểm toán nội bộ: đối tượng áp dụng, nguyên tắc độc lập và quy chế kiểm toán nội bộ.","Chuẩn mực Kiểm toán nội bộ toàn cầu của IIA (Global Internal Audit Standards, ban hành 2024).","Khung kiểm soát nội bộ COSO 2013 với 5 thành phần và 17 nguyên tắc.","Mô hình Ba tuyến của IIA (2020) về vai trò quản lý, quản trị rủi ro và kiểm toán nội bộ.","Quản trị rủi ro doanh nghiệp theo COSO ERM 2017 và ISO 31000:2018."],en:["Decree 05/2019/ND-CP on internal audit: scope, independence principles and the internal audit charter.","The IIA Global Internal Audit Standards (issued 2024).","The COSO 2013 internal control framework with 5 components and 17 principles.","The IIA Three Lines Model (2020) on management, risk and internal audit roles.","Enterprise risk management under COSO ERM 2017 and ISO 31000:2018."]},tools:["SQL / Python phân tích dữ liệu","Phần mềm quản lý kiểm toán và giấy làm việc","Công cụ phân tích dữ liệu kiểm toán (CAAT)","Microsoft Excel","Bảng điều khiển theo dõi khắc phục phát hiện"],kpis:{vi:["Tỷ lệ hoàn thành kế hoạch kiểm toán năm đã phê duyệt.","Tỷ lệ khuyến nghị được khắc phục đúng hạn.","Mức độ hài lòng của Ủy ban Kiểm toán và đơn vị được kiểm toán.","Tỷ lệ cuộc kiểm toán có sử dụng phân tích toàn bộ dữ liệu."],en:["Completion of the approved annual audit plan.","Share of recommendations remediated on time.","Satisfaction of the Audit Committee and auditees.","Share of audits using full-population data analytics."]},day:[{time:"08:30",vi:"Rà soát danh sách khuyến nghị quá hạn và nhắc các đơn vị cập nhật tiến độ.",en:"Review overdue recommendations and remind units to update progress."},{time:"10:00",vi:"Chạy truy vấn phát hiện PO tách đơn và thanh toán trùng trên dữ liệu ERP.",en:"Run queries for split POs and duplicate payments on ERP data."},{time:"13:30",vi:"Phỏng vấn trưởng phòng mua hàng và kiểm tra hồ sơ phê duyệt của mẫu chọn.",en:"Interview the procurement head and inspect approval files for selected samples."},{time:"15:30",vi:"Viết phát hiện theo cấu trúc tiêu chí, thực trạng, nguyên nhân, ảnh hưởng, khuyến nghị.",en:"Write findings as criteria, condition, cause, effect and recommendation."},{time:"17:00",vi:"Họp kết thúc với đơn vị được kiểm toán để thống nhất kế hoạch khắc phục.",en:"Hold the closing meeting with the auditee to agree remediation plans."}],mistakes:{vi:["Kiểm tra từng PO riêng lẻ mà không cộng gộp, bỏ sót hành vi tách đơn né hạn mức.","Chỉ kiểm tra thiết kế kiểm soát trên giấy mà không kiểm thử vận hành thực tế.","Gỡ hoặc làm nhẹ phát hiện theo đề nghị của bên bị kiểm toán, mất tính độc lập."],en:["Testing POs one by one without aggregation, missing split orders that dodge limits.","Checking control design on paper without testing real operation.","Removing or softening findings at the auditee's request, losing independence."]},career:[{vi:"Chuyên viên kiểm toán nội bộ",en:"Internal audit associate"},{vi:"Kiểm toán viên nội bộ chính",en:"Senior internal auditor"},{vi:"Quản lý kiểm toán nội bộ",en:"Internal audit manager"},{vi:"Trưởng Kiểm toán nội bộ (CAE)",en:"Chief Audit Executive (CAE)"}],glossary:[{term:"DOA",vi:"Ma trận phân quyền: quy định ai được phê duyệt loại giao dịch nào, đến hạn mức bao nhiêu.",en:"Delegation of authority: who may approve which transactions and up to what limit."},{term:"Split purchase",vi:"Tách đơn mua: chia một nhu cầu thành nhiều PO nhỏ để né hạn mức phê duyệt hoặc đấu thầu.",en:"Splitting one need into several small POs to dodge approval or tender limits."},{term:"Operating deficiency",vi:"Khiếm khuyết vận hành: kiểm soát được thiết kế đúng nhưng không được thực hiện như quy định.",en:"A well-designed control that is not performed as intended."},{term:"Three Lines Model",vi:"Mô hình Ba tuyến: quản lý vận hành, chức năng rủi ro tuân thủ và kiểm toán nội bộ độc lập.",en:"Operational management, risk and compliance functions, and independent internal audit."},{term:"Management response",vi:"Ý kiến phản hồi của quản lý về phát hiện, gồm hành động khắc phục, người phụ trách và thời hạn.",en:"Management's reply to a finding with actions, owner and deadline."}],quiz:[{q:{vi:"Kiểm thử 60 mẫu phát hiện 3 ngoại lệ; tỷ lệ sai lệch chấp nhận được là 4%. Kết luận nào đúng?",en:"Testing 60 samples finds 3 exceptions; the tolerable deviation rate is 4%. Which conclusion is right?"},options:{vi:["Tỷ lệ 3%, kiểm soát hữu hiệu","Tỷ lệ 4%, vừa đạt ngưỡng","Tỷ lệ 5%, vượt ngưỡng nên kiểm soát không hữu hiệu","Không kết luận được vì mẫu nhỏ"],en:["Rate 3%, control effective","Rate 4%, just at the limit","Rate 5%, above the limit so the control is not effective","No conclusion because the sample is small"]},answer:2,explain:{vi:"3 / 60 = 5%, cao hơn 4% chấp nhận được nên kết luận kiểm soát vận hành không hữu hiệu.",en:"3 / 60 = 5%, above the 4% tolerable rate, so the control is not operating effectively."}},{q:{vi:"Theo Mô hình Ba tuyến của IIA, kiểm toán nội bộ giữ vai trò nào?",en:"In the IIA Three Lines Model, what role does internal audit play?"},options:{vi:["Cung cấp đảm bảo độc lập, khách quan cho cơ quan quản trị","Trực tiếp vận hành kiểm soát hằng ngày","Thay ban điều hành ra quyết định rủi ro","Phê duyệt giao dịch mua sắm lớn"],en:["Provide independent, objective assurance to the governing body","Run daily controls directly","Make risk decisions instead of management","Approve large purchases"]},answer:0,explain:{vi:"Kiểm toán nội bộ độc lập với quản lý, báo cáo cho cơ quan quản trị và không làm thay chức năng vận hành.",en:"Internal audit is independent of management, reports to the governing body and does not perform operational roles."}},{q:{vi:"Thành phần nào KHÔNG thuộc 5 thành phần của khung kiểm soát nội bộ COSO 2013?",en:"Which is NOT one of the five components of the COSO 2013 framework?"},options:{vi:["Môi trường kiểm soát","Đánh giá rủi ro","Thông tin và truyền thông","Kiểm toán độc lập"],en:["Control environment","Risk assessment","Information and communication","External audit"]},answer:3,explain:{vi:"Năm thành phần là môi trường kiểm soát, đánh giá rủi ro, hoạt động kiểm soát, thông tin và truyền thông, giám sát.",en:"The five are control environment, risk assessment, control activities, information and communication, and monitoring."}},{q:{vi:"Người bị kiểm toán đề nghị đề cử bạn vào vị trí mới nếu bỏ một phát hiện. Bạn làm gì?",en:"An auditee offers to nominate you for a new role if you drop a finding. What do you do?"},options:{vi:["Nhận lời vì phát hiện không quá lớn","Từ chối, giữ phát hiện và báo Trưởng KTNB, Ủy ban Kiểm toán về áp lực","Làm nhẹ mức xếp hạng rủi ro","Chuyển phát hiện sang năm sau"],en:["Accept since the finding is small","Refuse, keep the finding and report the pressure to the CAE and Audit Committee","Lower the risk rating","Move the finding to next year"]},answer:1,explain:{vi:"Lợi ích cá nhân đổi lấy việc bỏ phát hiện đe dọa nghiêm trọng tính độc lập; phải từ chối và báo cáo.",en:"Personal benefits for dropping findings seriously threaten independence; refuse and report."}}],tools_en:["SQL / Python for data analytics","Audit management and workpaper software","Computer-assisted audit tools (CAAT)","Microsoft Excel","Audit finding remediation dashboard"]}}})})(window.KKR);
